import { Mesh, PlaneGeometry, Group, PlaneGeometry as Plane, Color, DoubleSide, FrontSide, MeshStandardNodeMaterial, MeshBasicNodeMaterial, AmbientLight, DirectionalLight, PointLight } from 'three/webgpu';
import { vec3, vec4, uv, mix, smoothstep, uniform, float, time, pow } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const colors = config.intent?.visualSpec?.colors ?? { ink:'#16161d', paper:'#e8ecf2', accent:'#ff2a38', surface:'#0b0b10' };
  const accent = new THREE.Color(colors.accent);
  const ink = new THREE.Color(colors.ink);
  const surface = new THREE.Color(colors.surface);
  const paper = new THREE.Color(colors.paper);

  const group = new THREE.Group();
  group.name = 'journal-card-3';

  // ------- Stage backdrop -------
  const backdropMat = new MeshBasicNodeMaterial({ side: FrontSide, toneMapped: true });
  const gradTop = uniform(vec3(surface.r, surface.g, surface.b));
  const gradMid = uniform(vec3(0.06, 0.06, 0.09));
  const gradBot = uniform(vec3(0.02, 0.02, 0.04));
  const v = uv().y;
  const gcol = mix(gradTop, gradMid, smoothstep(float(0.0), float(0.55), v));
  backdropMat.colorNode = mix(gcol, gradBot, smoothstep(float(0.55), float(1.0), v));
  const backdrop = new THREE.Mesh(new THREE.PlaneGeometry(8, 6), backdropMat);
  backdrop.position.set(0, 0, -2.5);
  backdrop.renderOrder = -10;
  group.add(backdrop);

  // Accent haze behind card (engineered, not pastel blur)
  const hazeMat = new MeshBasicNodeMaterial({ side: FrontSide, transparent: true, toneMapped: true });
  const hp = uv();
  const hd = pow(hp.x.sub(0.5).mul(2.0).pow(2).add(hp.y.sub(0.5).mul(2.0).pow(2)), float(0.5));
  hazeMat.colorNode = vec4(accent.r, accent.g, accent.b, smoothstep(float(1.0), float(0.0), hd).mul(0.12));
  const haze = new THREE.Mesh(new THREE.PlaneGeometry(3.4, 3.4), hazeMat);
  haze.position.set(0, 0, -1.2);
  group.add(haze);

  // ------- Card body (textured plane) -------
  const cardGroup = new THREE.Group();
  cardGroup.position.set(0, 0, 0);
  group.add(cardGroup);

  // Card geometry (image ratio 512x320 => 1.6)
  const cardW = 1.9, cardH = 1.18;
  const cardGeo = new THREE.BoxGeometry(cardW, cardH, 0.08, 1, 1, 1);
  // bevel via separate thin frame plane approach — keep simple PBR extruded
  const cardMat = new MeshStandardNodeMaterial({
    metalness: 0.45,
    roughness: 0.52,
    clearcoat: 0.22,
    clearcoatRoughness: 0.5,
    color: new THREE.Color(0x101015),
    side: FrontSide,
    toneMapped: true,
  });

  // Face/place image on front via separate plane
  const faceGeo = new THREE.PlaneGeometry(cardW * 0.96, cardH * 0.72);
  const faceMat = new MeshStandardNodeMaterial({
    metalness: 0.2,
    roughness: 0.6,
    color: new THREE.Color(0xffffff),
    toneMapped: true,
  });

  // Load image texture
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      faceMat.map = tex;
      faceMat.needsUpdate = true;
    }).catch(() => {});
  }

  const card = new THREE.Mesh(cardGeo, cardMat);
  card.position.set(0, 0, 0);
  card.castShadow = false;
  card.receiveShadow = false;
  cardGroup.add(card);

  // Face plane (image)
  const face = new THREE.Mesh(faceGeo, faceMat);
  face.position.set(0, 0.18, 0.041);
  cardGroup.add(face);

  // Accent edge bar (focus indicator) — thin emissive strip on left vertical edge
  const edgeMat = new THREE.MeshStandardNodeMaterial({
    metalness: 0.3,
    roughness: 0.4,
    color: new THREE.Color(0x0a0a0e),
    emissive: new THREE.Color(colors.accent),
    emissiveIntensity: 0.0,
    toneMapped: true,
  });
  const edgeBar = new THREE.Mesh(
    new THREE.BoxGeometry(0.04, cardH * 0.96, 0.10),
    edgeMat
  );
  edgeBar.position.set(-cardW / 2 + 0.02, 0, 0.01);
  cardGroup.add(edgeBar);

  // ------- Caption / label strip (paper) -------
  const stripGeo = new THREE.PlaneGeometry(cardW * 0.96, cardH * 0.28);
  const stripMat = new MeshStandardNodeMaterial({
    metalness: 0.1,
    roughness: 0.7,
    color: new THREE.Color(0x0e0e14),
    toneMapped: true,
  });
  const strip = new THREE.Mesh(stripGeo, stripMat);
  strip.position.set(0, -0.30, 0.041);
  cardGroup.add(strip);

  // Text from items (verbatim). If none, use stock label derived from binding.
  const captionText = items.find(i => i.role === 'caption' || i.role === 'label');
  const headlineText = items.find(i => i.role === 'title' || i.role === 'headline');

  const label = ctx.fontAtlas.createText(
    headlineText?.text ?? 'Journal 03',
    { fontSize: 0.11, color: colors.paper, align: 'left', letterSpacingPx: 3 }
  );
  label.position.set(-cardW * 0.46, -0.24, 0.045);
  cardGroup.add(label);

  const sub = ctx.fontAtlas.createText(
    captionText?.text ?? 'Issue · Atelier Log',
    { fontSize: 0.05, color: '#8a8a96', align: 'left', letterSpacingPx: 4 }
  );
  sub.position.set(-cardW * 0.46, -0.36, 0.045);
  cardGroup.add(sub);

  // Stock badge (bound to trpc.inventory.status.inStock). Default placeholder state.
  // We render an indicator dot + small mono caption.
  const badgeGroup = new THREE.Group();
  badgeGroup.position.set(cardW * 0.46 - 0.06, -0.32, 0.045);
  cardGroup.add(badgeGroup);

  const dotMat = new MeshStandardNodeMaterial({
    metalness: 0.1,
    roughness: 0.5,
    color: new THREE.Color(colors.accent),
    emissive: new THREE.Color(colors.accent),
    emissiveIntensity: 1.2,
    toneMapped: true,
  });
  const dot = new THREE.Mesh(new THREE.CircleGeometry(0.025, 16), dotMat);
  dot.position.set(-0.0, 0.0, 0.001);
  badgeGroup.add(dot);

  const stockVal = new THREE.MeshStandardNodeMaterial({
    metalness: 0.1, roughness: 0.6, color: new THREE.Color(0x8a8a96), toneMapped: true,
  });
  // use emissive only on dot; caption stays matte
  const stockCap = ctx.fontAtlas.createText('IN STOCK', { fontSize: 0.04, color: '#9a9aa3', align: 'right', letterSpacingPx: 3 });
  stockCap.position.set(-0.05, -0.018, 0.001);
  badgeGroup.add(stockCap);

  // set userData state hooks for binding
  group.userData.stockBadge = { dot, cap: stockCap, dotMat };

  // ------- Lights (node-local) -------
  const amb = new THREE.AmbientLight(0xffffff, 0.55);
  group.add(amb);

  const key = new THREE.DirectionalLight(0xffffff, 1.15);
  key.position.set(2.2, 2.0, 3.0);
  group.add(key);

  const rim = new THREE.DirectionalLight(accent, 0.7);
  rim.position.set(-2.2, -0.6, -1.5);
  group.add(rim);

  const back = new THREE.DirectionalLight(0xeaf0ff, 0.4);
  back.position.set(-1.5, 1.2, -2.0);
  group.add(back);

  // Apply scale to whole group before placement so card sits at z=0
  group.scale.set(1, 1, 1);

  // Entrance: rise-in
  const tl = gsap.timeline();
  cardGroup.position.y = 0.4;
  cardGroup.scale.set(0.96, 0.96, 0.96);
  tl.to(cardGroup.position, { y: 0, duration: 0.7, ease: 'power3.out' }, 0)
    .to(cardGroup.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.5, ease: 'power2.out' }, 0.3)
    .to(cardGroup.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' }, 0.8);

  // Gentle idle breathing on the haze
  const idle = gsap.timeline({ repeat: -1, yoyo: true });
  idle.to(haze.position, { z: -1.05, duration: 4.5, ease: 'sine.inOut' });

  // Interaction states
  let hovered = false;
  let pressed = false;
  const baseY = 0;
  const hoverLift = 0.15;

  function setHover(state) {
    hovered = state;
    const liftY = hovered ? baseY + hoverLift : baseY;
    gsap.to(cardGroup.position, { y: liftY, duration: 0.45, ease: 'power3.out' });
    gsap.to(edgeMat, { emissiveIntensity: hovered ? 1.8 : 0.0, duration: 0.35, ease: 'power2.out' });
    gsap.to(cardGroup.rotation, { x: hovered ? -0.04 : 0, duration: 0.4, ease: 'power2.out' });
  }

  function pressDown() {
    pressed = true;
    gsap.timeline()
      .to(cardGroup.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'power2.out' })
      .to(cardGroup.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.5, ease: 'power3.out' })
      .eventCallback('onComplete', () => { pressed = false; });
    // pulse accent edge
    gsap.fromTo(edgeMat, { emissiveIntensity: 2.2 }, { emissiveIntensity: 0.6, duration: 0.6, ease: 'power2.out' });
  }

  function onClick() {
    pressDown();
    ctx.emit('hub-journal.select', { card: 3 });
  }

  // handlers attach to returned object's userData
  group.userData.handlers = {
    onPointerEnter: () => setHover(true),
    onPointerLeave: () => setHover(false),
    onPointerDown: () => pressDown(),
    onClick: () => onClick(),
    inventoryStatus: (status) => {
      // binding target: stockBadge
      if (status && typeof status.inStock !== 'undefined') {
        const { dotMat } = group.userData.stockBadge;
        if (status.inStock) {
          dotMat.emissive = new THREE.Color(colors.accent);
          dotMat.color = new THREE.Color(colors.accent);
          dotMat.emissiveIntensity = 1.4;
          group.userData.stockBadge.cap.visible = true;
          // update caption text remains static placeholder; swap not supported without re-create
        } else {
          dotMat.emissive = new THREE.Color('#3a3a44');
          dotMat.color = new THREE.Color('#1a1a22');
          dotMat.emissiveIntensity = 0.3;
        }
      }
    },
  };

  // Cleanup
  const cleanups = [];
  group.userData.cleanup = () => {
    tl.kill();
    idle.kill();
    gsap.killTweensOf(cardGroup.position);
    gsap.killTweensOf(cardGroup.scale);
    gsap.killTweensOf(cardGroup.rotation);
    gsap.killTweensOf(edgeMat);
    gsap.killTweensOf(haze.position);
    cardGeo.dispose();
    faceGeo.dispose();
    stripGeo.dispose();
    edgeBar.geometry.dispose();
    dot.geometry.dispose();
    cardMat.dispose();
    faceMat.dispose();
    stripMat.dispose();
    edgeMat.dispose();
    dotMat.dispose();
    stockVal.dispose();
    backdropMat.dispose();
    backdrop.geometry.dispose();
    hazeMat.dispose();
    haze.geometry.dispose();
    cleanups.forEach(fn => { try { fn(); } catch (e) {} });
  };

  return group;
}
